with RecursiveDirectTagHierarchy as (
    select t.Id, t.TagName, t.Count,
           as_tree_level = 1,
           array[t.Id] as path_ids
    from Tags t
    where t.IsRequired = 1
  
  union all
  
    select c.Id, c.TagName, c.Count,
           as_tree_level = h.as_tree_level + 1,
           path_ids || c.Id
    from Tags c
    inner join RecursiveDirectTagHierarchy h on c.IsModeratorOnly = 0 and -- emulated parent relationship (adjacency differentiated by difference in count)
